if isLocalWin then
    local file = io.open("gameconfig.json")
    if file then
        local content = file:read("*a")
        file:close()
        local data = json.decode(content)
        local port = isClient and 9966 or 9967
        if data.debug_cpath then
            package.cpath = package.cpath .. data.debug_cpath
            local dbg = require('emmy_core')
            local res, _ = pcall(dbg.tcpListen, "localhost", port)
            while not res do
                if isClient then
                    port = port - 1
                else
                    port = port + 1
                end
                res, _ = pcall(dbg.tcpListen, "localhost", port)
            end
        end
    end
end

function isLocalDb()
    if not isLocalWin then
        return false
    end
    local file = io.open("gameconfig.json")
    if not file then
        return false
    end
    local content = file:read("*a")
    file:close()
    local data = json.decode(content)
    if data.local_db == nil then
        return true
    end
    return data.local_db
end

function loadWindowHttpHost()
    if not isLocalWin then
        return
    end
    local file = io.open("gameconfig.json")
    if not file then
        return false
    end
    local content = file:read("*a")
    file:close()
    local data = json.decode(content)
    if not data.region then
        return
    end
    if isClient then
        if data.client_web_http_host then
            WebService:setHttpHost(data.client_web_http_host[data.region])
        end
    else
        if data.web_http_host then
            WebService.ServerHttpHost = data.web_http_host[data.region] or WebService.ServerHttpHost
            WebService.ServerHttpRetryHost = WebService.ServerHttpHost
        end
        if data.db_http_host ~= nil then
            WebService.DBHttpHost = data.db_http_host[data.region] or WebService.DBHttpHost
            WebService.DBHttpRetryHost = WebService.DBHttpHost
        end
    end
end

function getLocalGameMode()
    if not isLocalWin then
        return nil
    end
    local file = io.open("gameconfig.json")
    if not file then
        return nil
    end
    local content = file:read("*a")
    file:close()
    local data = json.decode(content)
    if data.tags then
        return data.tags.gameMode
    end
    return nil
end